<script>
(()=>{const editor=document.getElementById('page-editor'),source=document.getElementById('content'),form=source.form;document.querySelector('.blog-editor-toolbar').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;editor.focus();if(b.id==='page-link-button'){const url=prompt('Bağlantı adresi (https://, mailto: veya site içi /adres):');if(url&&/^(https?:\/\/|mailto:|\/)/i.test(url))document.execCommand('createLink',false,url);return}document.execCommand(b.dataset.cmd,false,b.dataset.value||null)});document.getElementById('page-image-button').addEventListener('click',()=>{const select=document.getElementById('page-media-select'),src=select.value;if(!src){select.focus();return}const figure=document.createElement('figure'),image=document.createElement('img'),caption=document.createElement('figcaption');image.src=src;image.alt=prompt('Görsel için kısa açıklama (boş bırakabilirsiniz):')||'';image.loading='lazy';figure.append(image,caption);editor.focus();document.execCommand('insertHTML',false,figure.outerHTML);select.value=''});form.addEventListener('submit',()=>source.value=editor.innerHTML)})();
</script>
